(()=>{const tab=document.querySelector('[data-panel="orders"]'),root=document.querySelector('#admin-member-orders');if(!tab||!root)return;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);async function load(){root.textContent='Carregando pedidos…';try{const res=await fetch('/api/admin/orders',{cache:'no-store'}),data=await res.json();if(!res.ok)throw Error(data.error);root.innerHTML=data.orders.length?data.orders.map(o=>`<article class="admin-row"><div class="details"><h3>Pedido ${esc(o.id.slice(0,8))} · ${o.demo?'Demonstração · ':''}${({pending:'Pendente',completed:'Concluído',cancelled:'Cancelado'})[o.status]}</h3><p>${esc(o.name)} · ${esc(o.email)}</p><p>${o.customer?.phone?`Telefone: ${esc(o.customer.phone)}`:""}</p>${o.customer?.street?`<details><summary>Dados de entrega</summary><p>${esc(o.customer.fullName)}</p><p>${esc(o.customer.street)}, ${esc(o.customer.number)} ${esc(o.customer.complement)}</p><p>${esc(o.customer.neighborhood)} · ${esc(o.customer.city)}/${esc(o.customer.state)} · CEP ${esc(o.customer.cep)}</p><p>CPF: ***.***.***-${esc(o.customer.cpf.slice(-2))}</p></details>`:""}<p>${new Date(o.createdAt).toLocaleString('pt-BR')}</p><p>${o.items.map(p=>`${p.quantity} × ${esc(p.name)}`).join('<br>')}</p><strong>${money(o.total)}</strong>${o.status==='pending'?`<p>Confirme a conclusão somente após verificar pagamento e entrega.${o.demo?' Este pedido de teste libera avaliações identificadas como demonstração.':''}</p><div class="row-actions"><button data-status="completed" data-order="${o.id}">Confirmar compra concluída</button><button data-status="cancelled" data-order="${o.id}">Cancelar pedido</button></div>`:''}</div></article>`).join(''):'<p class="empty">Nenhum pedido registrado.</p>'}catch(e){root.textContent=e.message}}tab.addEventListener('click',load);document.querySelector('#refresh-member-orders').onclick=load;root.onclick=async e=>{const button=e.target.closest('[data-order]');if(!button)return;const question=button.dataset.status==='completed'?'Confirma que o pagamento e a entrega deste pedido foram concluídos?':'Deseja cancelar este pedido?';if(!confirm(question))return;button.disabled=true;try{const r=await fetch('/api/admin/orders/status',{method:'POST',headers:{'Content-Type':'application/json','X-SOS-Member':'1'},body:JSON.stringify({id:button.dataset.order,status:button.dataset.status})});const data=await r.json();if(!r.ok)throw Error(data.error);await load()}catch(e){root.textContent=e.message}}})();
